import numpy as np
d = np.load('source_pixels.npz')
rgb = d['rgb'].astype(int)
def hue_char(p):
    r,g,b=p
    mx=max(r,g,b); mn=min(r,g,b)
    if mx-mn<25:
        return '.' if mx>200 else ('#' if mx<80 else 'o')
    if r>=g and r>=b:
        return 'R' if r-g>40 else 'r'
    if g>=r and g>=b: return 'G'
    return 'B'
for t in [0,8,16,24,32,40,50]:
    print('=== frame',t)
    f=rgb[t]
    for yy in range(52,102,2):
        line=''
        for xx in range(58,178,2):
            line+=hue_char(f[yy,xx])
        print(line)
\""
